<?php

declare(strict_types=1);

namespace AndyDefer\Actions\Enums;

/**
 * Defines all available HTTP response types that can be generated by ResponseFactory.
 *
 * This enum maps each response type to its string representation, which is used
 * internally by ResponseFactory to determine which conversion method to call
 * when toResponse() is invoked.
 *
 * Each case corresponds to a specific HTTP response type:
 * - JSON: API JSON responses
 * - REDIRECT: HTTP redirects to URLs
 * - REDIRECT_ROUTE: HTTP redirects to named routes
 * - REDIRECT_BACK: HTTP redirects to the previous page
 * - STREAM: Streamed responses for large data transfer
 * - SSE: Server-Sent Events for real-time notifications
 * - NO_CONTENT: 204 No Content responses
 * - INERTIA: Inertia.js responses for SPA applications
 * - HTML: Raw HTML responses
 * - FILE_INLINE: Files displayed inline in the browser
 * - FILE_DOWNLOAD: Files forced to download
 * - TEXT: Plain text responses
 * - VIEW: Blade view responses
 *
 * Classification invariants:
 * - isApi() and isWeb() are mutually exclusive.
 * - isFile() is orthogonal to isApi() and isWeb(): a file can be consumed
 *   by a browser or by a programmatic client. File types are therefore
 *   neither isApi() nor isWeb(), and callers must branch on isFile() before
 *   assuming an API/Web dichotomy.
 * - isPage() implies isWeb(); the reverse is not true (redirects are web
 *   but not pages).
 * - isRedirect() implies isWeb(); the reverse is not true (pages are web
 *   but not redirects).
 * - isEmpty() is orthogonal to isApi() and isWeb(); today only NO_CONTENT
 *   qualifies, and it is also isApi() (204 is a valid API response).
 *
 * @example
 * $type = HttpResponseType::JSON;
 * echo $type->value; // 'json'
 *
 * @author Andy Defer
 */
enum HttpResponseType: string
{
    /**
     * JSON response for API endpoints.
     *
     * Converts AbstractData objects to camelCase arrays automatically.
     */
    case JSON = 'json';

    /**
     * Redirect response to an absolute URL.
     */
    case REDIRECT = 'redirect';

    /**
     * Redirect response to a named route.
     */
    case REDIRECT_ROUTE = 'redirectRoute';

    /**
     * Redirect response back to the previous page.
     */
    case REDIRECT_BACK = 'redirectBack';

    /**
     * Streamed response for large data or real-time output.
     */
    case STREAM = 'stream';

    /**
     * Server-Sent Events response for real-time push notifications.
     */
    case SSE = 'sse';

    /**
     * 204 No Content response for successful requests without response body.
     */
    case NO_CONTENT = 'noContent';

    /**
     * Inertia.js response for modern single-page applications.
     */
    case INERTIA = 'inertia';

    /**
     * Raw HTML response for emails, legacy views, or external integrations.
     */
    case HTML = 'html';

    /**
     * File response with inline disposition (browser displays the file).
     */
    case FILE_INLINE = 'fileInline';

    /**
     * File response with attachment disposition (browser downloads the file).
     */
    case FILE_DOWNLOAD = 'fileDownload';

    /**
     * Plain text response for logs, configuration files, or simple endpoints.
     */
    case TEXT = 'text';

    /**
     * Blade view response for legacy Laravel views.
     */
    case VIEW = 'view';

    /**
     * Response types consumed by a programmatic client (mobile, SPA, service).
     *
     * True for: JSON, NO_CONTENT, TEXT, STREAM, SSE.
     * False for: web types and file types.
     */
    public function isApi(): bool
    {
        return match ($this) {
            self::JSON,
            self::NO_CONTENT,
            self::TEXT,
            self::STREAM,
            self::SSE => true,

            self::HTML,
            self::VIEW,
            self::INERTIA,
            self::REDIRECT,
            self::REDIRECT_ROUTE,
            self::REDIRECT_BACK,
            self::FILE_INLINE,
            self::FILE_DOWNLOAD => false,
        };
    }

    /**
     * Response types consumed by a browser (HTML render or browser navigation).
     *
     * True for: HTML, VIEW, INERTIA, REDIRECT, REDIRECT_ROUTE, REDIRECT_BACK.
     * False for: API types and file types.
     */
    public function isWeb(): bool
    {
        return match ($this) {
            self::HTML,
            self::VIEW,
            self::INERTIA,
            self::REDIRECT,
            self::REDIRECT_ROUTE,
            self::REDIRECT_BACK => true,

            self::JSON,
            self::NO_CONTENT,
            self::TEXT,
            self::STREAM,
            self::SSE,
            self::FILE_INLINE,
            self::FILE_DOWNLOAD => false,
        };
    }

    /**
     * Response types that render a page (HTML document, Blade view, Inertia page).
     *
     * True for: HTML, VIEW, INERTIA.
     * Implies isWeb() === true.
     */
    public function isPage(): bool
    {
        return match ($this) {
            self::HTML,
            self::VIEW,
            self::INERTIA => true,

            self::JSON,
            self::NO_CONTENT,
            self::TEXT,
            self::STREAM,
            self::SSE,
            self::REDIRECT,
            self::REDIRECT_ROUTE,
            self::REDIRECT_BACK,
            self::FILE_INLINE,
            self::FILE_DOWNLOAD => false,
        };
    }

    /**
     * Response types that return a binary file to the client.
     *
     * True for: FILE_INLINE, FILE_DOWNLOAD.
     * Orthogonal to isApi()/isWeb(): files are neither classified as API
     * nor Web. Callers that need an exhaustive classification must check
     * isFile() in addition to isApi()/isWeb().
     */
    public function isFile(): bool
    {
        return match ($this) {
            self::FILE_INLINE,
            self::FILE_DOWNLOAD => true,

            self::JSON,
            self::NO_CONTENT,
            self::TEXT,
            self::STREAM,
            self::SSE,
            self::HTML,
            self::VIEW,
            self::INERTIA,
            self::REDIRECT,
            self::REDIRECT_ROUTE,
            self::REDIRECT_BACK => false,
        };
    }

    /**
     * Response types that carry no body.
     *
     * True for: NO_CONTENT.
     * Orthogonal to isApi()/isWeb(): NO_CONTENT is also isApi().
     */
    public function isEmpty(): bool
    {
        return match ($this) {
            self::NO_CONTENT => true,

            self::JSON,
            self::TEXT,
            self::STREAM,
            self::SSE,
            self::HTML,
            self::VIEW,
            self::INERTIA,
            self::REDIRECT,
            self::REDIRECT_ROUTE,
            self::REDIRECT_BACK,
            self::FILE_INLINE,
            self::FILE_DOWNLOAD => false,
        };
    }

    /**
     * Response types that instruct the client to navigate elsewhere.
     *
     * True for: REDIRECT, REDIRECT_ROUTE, REDIRECT_BACK.
     * Implies isWeb() === true, but isPage() === false.
     */
    public function isRedirect(): bool
    {
        return match ($this) {
            self::REDIRECT,
            self::REDIRECT_ROUTE,
            self::REDIRECT_BACK => true,

            self::JSON,
            self::NO_CONTENT,
            self::TEXT,
            self::STREAM,
            self::SSE,
            self::HTML,
            self::VIEW,
            self::INERTIA,
            self::FILE_INLINE,
            self::FILE_DOWNLOAD => false,
        };
    }
}
